export function renderBoard(puzzle, pegs, selected, targets) {
  const board = document.getElementById('board');
  board.innerHTML = '';

  const cells = puzzle.cells;
  const xs = cells.map(c => parseInt(c.split(',')[0]));
  const ys = cells.map(c => parseInt(c.split(',')[1]));
  const minX = Math.min(...xs), maxX = Math.max(...xs);
  const minY = Math.min(...ys), maxY = Math.max(...ys);
  const cols = maxX - minX + 1;
  const rows = maxY - minY + 1;

  board.style.display = 'grid';
  board.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
  board.style.gridTemplateRows = `repeat(${rows}, 1fr)`;
  board.style.gap = '4px';
  board.style.aspectRatio = `${cols}/${rows}`;

  const pegSet = new Set(pegs);
  const goalSet = new Set(puzzle.goal);
  const targetSet = new Set(targets);

  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const cellId = `${x},${y}`;
      const isCell = cells.includes(cellId);
      if (!isCell) continue;

      const btn = document.createElement('button');
      btn.dataset.cell = cellId;
      btn.dataset.occupied = pegSet.has(cellId) ? 'true' : 'false';
      btn.setAttribute('aria-label', `Cell ${cellId}, ${pegSet.has(cellId) ? 'occupied' : 'empty'}`);

      if (pegSet.has(cellId)) btn.classList.add('peg');
      if (goalSet.has(cellId)) btn.classList.add('goal');
      if (selected === cellId) btn.classList.add('selected');
      if (targetSet.has(cellId)) btn.classList.add('target');

      btn.style.gridColumn = x - minX + 1;
      btn.style.gridRow = y - minY + 1;

      board.appendChild(btn);
    }
  }
}
